/**
 * Get the resolved color from a CSS custom property on an element.
 *
 * Resolves `light-dark()` values using the element's inherited color scheme,
 * including styles in its shadow root. Returns `undefined` if the property is
 * missing. The returned value is a CSS color string, not a parsed color.
 *
 * @public
 * @param element The element on which to read the custom property.
 * @param propertyName The CSS custom property containing a color.
 * @returns The resolved CSS color, or `undefined` if the property is missing.
 *
 * @example
 * ```ts
 * const textColor = getCssColor(element, "--app-text-color");
 * const fallbackColor = getCssColor(element, "--optional-color") ?? "black";
 * ```
 *
 * @example
 * ```css
 * .panel {
 *   color-scheme: dark;
 *   --panel-color: light-dark(#ffffff, #202020);
 * }
 * ```
 * ```ts
 * // Resolves to the dark color in the context of the panel.
 * const panelColor = getCssColor(panel, "--panel-color");
 * ```
 */
export declare function getCssColor(element: Element, propertyName: string): string | undefined;
/**
 * Get the effective light or dark color scheme for an element.
 *
 * A computed `color-scheme` containing only `light` or only `dark` takes
 * precedence. If both or neither are allowed, the system color preference
 * determines the result. This is a snapshot; call again after styles or the
 * system preference change.
 *
 * @public
 * @param element The element whose computed color scheme is used.
 * @returns The effective color scheme.
 *
 * @example
 * ```ts
 * // An element with `color-scheme: dark` returns "dark".
 * const scheme = getEffectiveColorScheme(element);
 * ```
 *
 * @example
 * ```ts
 * // With `color-scheme: light dark`, the preferred system scheme is returned.
 * const preferredScheme = getEffectiveColorScheme(element);
 * ```
 */
export declare function getEffectiveColorScheme(element: Element): "dark" | "light";
